-- KEYS[1]: prs:coupon:{couponId} (优惠券缓存)
-- KEYS[2]: prs:user:coupon:{couponId} (用户领取计数)
-- ARGV[1]: userId
--
-- 返回值:
--   1~5: 错误码(见 RECEIVE_COUPON_ERROR_MSG)
--   0:   成功

-- 1. 优惠券是否存在
if (redis.call('exists', KEYS[1]) == 0) then
    return 1
end

-- 2. 获取方式校验：只有「手动领取」的券允许走这个接口。
--    兑换码专属券（obtainWay=2）必须走 /exchange，否则拿到 couponId 就能白领。
--    老缓存没有该字段时按手动领取放行，避免上线瞬间全部报错。
local obtainWay = redis.call('hget', KEYS[1], 'obtainWay')
if (obtainWay and tonumber(obtainWay) ~= 1) then
    return 5
end

-- 2.5 券必须处于「发放中」(status=3)。
--     列表接口按 status 过滤了，但直接调接口可以绕过；暂停/待发放/已结束的券不该被领走。
--     老缓存没有该字段时跳过。
local status = redis.call('hget', KEYS[1], 'status')
if (status and tonumber(status) ~= 3) then
    return 7
end

-- 3. 是否已售罄
if (tonumber(redis.call('hget', KEYS[1], 'totalNum') or "0") <= 0) then
    return 2
end

-- 4. 校验有效期 (time[1]=秒, HGET存的issueEndTime=毫秒, 统一转为毫秒比较)
local now = redis.call('time')
local nowMs = tonumber(now[1]) * 1000 + tonumber(now[2]) / 1000
-- 未到开始时间：定时发放的券会提前预热缓存，这里必须挡住，否则活动开始前就能领
local issueBeginTime = tonumber(redis.call('hget', KEYS[1], 'issueBeginTime'))
if (issueBeginTime and nowMs < issueBeginTime) then
    return 6
end
local issueEndTime = tonumber(redis.call('hget', KEYS[1], 'issueEndTime'))
if (issueEndTime and nowMs > issueEndTime) then
    return 3
end

-- 5. 校验用户领取限额 (先HGET只读查询, 确认不超限再HINCRBY递增)
--    userLimit 缺省按 1 处理：nil 与 number 比较会让整个脚本抛错
local userLimit = tonumber(redis.call('hget', KEYS[1], 'userLimit') or "1")
local curCount = tonumber(redis.call('hget', KEYS[2], ARGV[1]) or "0")
if (curCount >= userLimit) then
    return 4
end
-- 6.递增用户领取计数
redis.call('hincrby', KEYS[2], ARGV[1], 1)

-- 7. 扣减库存
redis.call('hincrby', KEYS[1], "totalNum", -1)
return 0
